//! The pen sample: one reading from the tablet, in window pixels.

/// Where a sample came from.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum Source {
    Wintab,
    Ink,
    Mouse,
    /// Generated by tests or replay.
    Synthetic,
}

impl Source {
    pub const ALL: [Source; 4] = [Source::Wintab, Source::Ink, Source::Mouse, Source::Synthetic];

    pub fn as_str(self) -> &'static str {
        match self {
            Source::Wintab => "wintab",
            Source::Ink => "ink",
            Source::Mouse => "mouse",
            Source::Synthetic => "synthetic",
        }
    }

    pub fn parse(s: &str) -> Option<Source> {
        Source::ALL.into_iter().find(|src| src.as_str() == s)
    }

    pub fn label(self) -> &'static str {
        match self {
            Source::Wintab => "Wintab",
            Source::Ink => "Windows Ink",
            Source::Mouse => "Mouse",
            Source::Synthetic => "Synthetic",
        }
    }
}

/// Bit flags carried by a sample.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq, Hash)]
pub struct Flags(pub u32);

impl Flags {
    /// The pen tip (or eraser) touches the surface.
    pub const CONTACT: u32 = 1 << 0;
    /// The eraser end is being used (Wintab `TPS_INVERT`/eraser cursor, Ink `PEN_FLAG_INVERTED`/`PEN_FLAG_ERASER`).
    pub const ERASER: u32 = 1 << 1;
    /// First (lower) barrel button held.
    pub const BARREL1: u32 = 1 << 2;
    /// Second (upper) barrel button held.
    pub const BARREL2: u32 = 1 << 3;
    /// The device reported pressure for this sample.
    pub const HAS_PRESSURE: u32 = 1 << 4;
    /// The device reported tilt for this sample.
    pub const HAS_TILT: u32 = 1 << 5;
    /// The device reported barrel rotation / twist.
    pub const HAS_TWIST: u32 = 1 << 6;
    /// Wintab reported a queue overflow just before this packet.
    pub const QUEUE_ERROR: u32 = 1 << 7;
    /// Position came from the integer pixel location instead of the sub-pixel one.
    pub const COARSE_POSITION: u32 = 1 << 8;
    /// First sample after the pen came into range.
    pub const PROXIMITY_IN: u32 = 1 << 9;

    pub fn has(self, bit: u32) -> bool {
        self.0 & bit != 0
    }

    pub fn set(&mut self, bit: u32, on: bool) {
        if on {
            self.0 |= bit;
        } else {
            self.0 &= !bit;
        }
    }
}

/// One tablet reading.
///
/// Positions are in window client-area **physical** pixels (the app is per-monitor DPI aware),
/// with sub-pixel precision when the API provides it. Tilt follows the W3C Pointer Events
/// convention also used by Windows Ink: `tilt_x` is positive when the pen leans to the right,
/// `tilt_y` is positive when it leans toward the user, both in degrees within -90..=90.
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct PenSample {
    pub source: Source,
    /// When the device says the sample happened, on the app clock ([`crate::clock`]), in µs.
    pub t_us: u64,
    /// When the app received it, in µs.
    pub recv_us: u64,
    pub x: f64,
    pub y: f64,
    /// Normalised pressure 0..=1.
    pub pressure: f32,
    pub tilt_x: f32,
    pub tilt_y: f32,
    /// Barrel rotation / twist in degrees (0 when not reported).
    pub twist: f32,
    pub flags: Flags,
    /// Pressure exactly as the API reported it (Wintab: device units, Ink: 0..=1024).
    pub raw_pressure: u32,
    /// Button state exactly as the API reported it (Wintab `pkButtons`, Ink `penFlags`).
    pub raw_buttons: u32,
    /// Wintab packet serial number, Ink frame id, mouse: 0.
    pub serial: u32,
    /// Wintab cursor index, Ink pointer id, mouse: 0.
    pub cursor: u32,
}

impl PenSample {
    pub fn contact(&self) -> bool {
        self.flags.has(Flags::CONTACT)
    }

    pub fn eraser(&self) -> bool {
        self.flags.has(Flags::ERASER)
    }

    /// A plain sample for tests and synthetic input.
    pub fn synthetic(t_us: u64, x: f64, y: f64, pressure: f32, contact: bool) -> PenSample {
        let mut flags = Flags(Flags::HAS_PRESSURE);
        flags.set(Flags::CONTACT, contact);
        PenSample {
            source: Source::Synthetic,
            t_us,
            recv_us: t_us,
            x,
            y,
            pressure,
            tilt_x: 0.0,
            tilt_y: 0.0,
            twist: 0.0,
            flags,
            raw_pressure: (pressure * 1024.0).round() as u32,
            raw_buttons: 0,
            serial: 0,
            cursor: 0,
        }
    }
}
